      {word: "market", def: "A system in which goods and services are bought and sold, with prices set by supply and demand.", syn: "marketplace", ant: "command economy", use: "The Market Revolution tied distant farms and factories together in one national market."},
      {word: "cotton", def: "The soft fiber grown on cotton plants; in the 1800s it became America's most valuable export, grown by enslaved labor.", syn: "fiber", ant: "synthetic", use: "Cotton profits linked Southern plantations, Northern mills, and British factories in one economy."},
      {word: "industrialization", def: "The process by which an economy shifts from farming to large-scale manufacturing.", syn: "mechanization", ant: "deindustrialization", use: "The Market Revolution drove rapid industrialization across the northern states."},
      {word: "vertebrate", def: "An animal with a backbone or spinal column.", syn: "chordate", ant: "invertebrate", use: "Whales are vertebrates despite living entirely in the ocean."},
      {word: "entrepreneur", def: "A person who starts and runs a business, taking on financial risk to do so.", syn: "businessperson", ant: "employee", use: "Mill owners became wealthy entrepreneurs during the Market Revolution."}
