      {word: "secession", def: "The formal withdrawal of a state or region from a larger political union.", syn: "withdrawal", ant: "union", use: "South Carolina's nullification crisis raised the threat of secession."},
      {word: "homeostasis", def: "The tendency of the body to maintain stable internal conditions, such as temperature.", syn: "equilibrium", ant: "imbalance", use: "The endocrine system helps the body maintain homeostasis during stress."},
      {word: "compact", def: "A formal agreement or contract between parties, especially states or nations.", syn: "treaty", ant: "breach", use: "Nullifiers argued the Constitution was a compact among sovereign states."}
